function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function load(name: string): Promise<void> {
  console.log(`${name} 開始`);
  await wait(100);
  console.log(`${name} 完了`);
}

